import json, glob, os

def aggregate():
    files = sorted(glob.glob('records_*.jsonl'))
    total = 0
    for f in files:
        with open(f, 'r') as fr:
            for line in fr:
                total += int(json.loads(line)['count'])
    with open('aggregates.json', 'w') as wf:
        json.dump({'total_records': total}, wf)

if __name__ == '__main__':
    aggregate()

